package ua.empirecraft.feudal;
import java.sql.SQLException;
import java.util.*;
import static ua.empirecraft.feudal.Database.*;
import static ua.empirecraft.feudal.Model.*;
import ua.empirecraft.feudal.FeudalService.Actor;

/** Escrow at creation, one executor, partial deposits and durable resource claims. */
public final class OrderService {
    private final FeudalService s;private final Database db;
    public OrderService(FeudalService s) throws SQLException {this.s=s;db=s.db;
        db.execute("CREATE TABLE IF NOT EXISTS resource_orders (id VARCHAR(36) PRIMARY KEY,issuer VARCHAR(100),creator VARCHAR(36),worker VARCHAR(36),sample CLOB,item_name VARCHAR(160),quantity BIGINT,delivered BIGINT,reward BIGINT,code VARCHAR(8),status VARCHAR(16),created BIGINT,expires BIGINT)");
        db.execute("CREATE TABLE IF NOT EXISTS order_claims (id VARCHAR(36) PRIMARY KEY,owner VARCHAR(100),quantity BIGINT CHECK(quantity>=0))");
        db.execute("CREATE TABLE IF NOT EXISTS order_item_ops (id VARCHAR(36) PRIMARY KEY,order_id VARCHAR(36),actor VARCHAR(36),direction VARCHAR(3),quantity BIGINT,status VARCHAR(16),before_items CLOB,after_items CLOB,created BIGINT)");
        db.execute("CREATE TABLE IF NOT EXISTS order_history (seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id VARCHAR(36),at_time BIGINT,actor VARCHAR(80),event VARCHAR(32),detail CLOB)");}
    private void owned(Actor actor,String owner) throws SQLException {if(owner.equals("p:"+actor.id()))return;require(owner.startsWith("e:"),"Чужий особистий рахунок.");s.controlTreasury(actor,s.estate(owner.substring(2)));}
    private void log(String id,Actor actor,String event,String detail) throws SQLException {db.execute("INSERT INTO order_history(id,at_time,actor,event,detail) VALUES(?,?,?,?,?)",id,s.now(),actor.id(),event,detail);s.audit(actor,"ORDER_"+event,id+" "+detail);}
    public Map<String,Object> get(String id) throws SQLException {var row=db.one("SELECT * FROM resource_orders WHERE id=?",id);require(row!=null,"Замовлення не знайдено.");return row;}
    private boolean uncertain(String id) throws SQLException {return db.one("SELECT id FROM order_item_ops WHERE order_id=? AND status='PREPARED'",id)!=null;}
    public String create(Actor actor,String issuer,String sample,String name,long qty,long reward,String code,int days){return db.transaction(()->{
        owned(actor,issuer);if(issuer.startsWith("e:"))require(s.estate(issuer.substring(2)).active(),"Неактивне володіння не створює замовлень.");require(qty>=1&&qty<=1_000_000&&reward>0&&reward<=CurrencyService.MAX_MONEY&&days>=1&&days<=30,"Кількість: 1–1000000; оплата додатна; строк: 1–30 днів.");require(sample!=null&&!sample.isBlank()&&name!=null&&name.length()<=160,"Немає зразка предмета.");s.currency(code);require(s.balance(issuer,code)>=reward,"Недостатньо монет для резервування.");require(number(db.one("SELECT COUNT(*) AS n FROM resource_orders WHERE issuer=? AND status IN ('OPEN','WORKING')",issuer),"n")<20,"Ліміт: 20 активних замовлень на замовника.");
        String id=UUID.randomUUID().toString();s.setBalance(issuer,code,s.balance(issuer,code)-reward);s.setBalance("o:"+id,code,reward);db.execute("INSERT INTO resource_orders VALUES(?,?,?,NULL,?,?,?,0,?,?,'OPEN',?,?)",id,issuer,actor.id(),sample,name,qty,reward,code,s.now(),s.now()+days*FeudalService.DAY);log(id,actor,"CREATE",qty+" "+name+" за "+format(reward)+" "+code+"; резерв="+issuer);return id;
    });}
    public void take(Actor actor,String id){db.transaction(()->{var o=get(id);require("OPEN".equals(string(o,"status"))&&s.now()<number(o,"expires"),"Замовлення вже зайняте або завершене.");require(!string(o,"issuer").equals("p:"+actor.id()),"Не можна виконувати власне особисте замовлення.");db.execute("UPDATE resource_orders SET worker=?,status='WORKING' WHERE id=?",actor.id(),id);log(id,actor,"TAKE","Виконавець погодив умови");return null;});}
    public String prepare(Actor actor,String id,boolean delivery,long n,String before,String after){return db.transaction(()->{
        var o=get(id);require(!uncertain(id),"Попередня передача ресурсів потребує перевірки адміністратора.");require(db.one("SELECT id FROM order_item_ops WHERE actor=? AND status='PREPARED'",actor.id())==null,"У вас є незавершена передача ресурсів.");require(n>0&&before!=null&&after!=null&&!before.equals(after),"Немає передачі ресурсів.");
        if(delivery){require("WORKING".equals(string(o,"status"))&&actor.id().equals(string(o,"worker"))&&s.now()<number(o,"expires"),"Здавати може призначений виконавець до завершення строку.");require(n<=number(o,"quantity")-number(o,"delivered"),"Забагато ресурсів.");if(n==number(o,"quantity")-number(o,"delivered"))require(Math.addExact(s.balance("p:"+actor.id(),string(o,"code")),number(o,"reward"))<=CurrencyService.MAX_MONEY,"Ліміт балансу виконавця.");}
        else{var claim=db.one("SELECT * FROM order_claims WHERE id=?",id);require(claim!=null,"Немає ресурсів для отримання.");owned(actor,string(claim,"owner"));require(n<=number(claim,"quantity"),"Забагато ресурсів для отримання.");}
        String op=UUID.randomUUID().toString();db.execute("INSERT INTO order_item_ops VALUES(?,?,?,?,?,'PREPARED',?,?,?)",op,id,actor.id(),delivery?"IN":"OUT",n,before,after,s.now());log(id,actor,"PREPARE",op+" "+n);return op;
    });}
    public Map<String,Object> operation(String id) throws SQLException {var op=db.one("SELECT * FROM order_item_ops WHERE id=?",id);require(op!=null,"Операцію не знайдено.");return op;}
    public void finish(Actor actor,String id,boolean applied){db.transaction(()->{
        var op=operation(id);require(actor.admin()||actor.id().equals(string(op,"actor")),"Немає доступу.");require("PREPARED".equals(string(op,"status")),"Передачу вже завершено.");String oid=string(op,"order_id");var o=get(oid);long n=number(op,"quantity");
        if(applied){if("IN".equals(string(op,"direction"))){long delivered=Math.addExact(number(o,"delivered"),n);require(delivered<=number(o,"quantity"),"Пошкоджена кількість ресурсів.");db.execute("UPDATE resource_orders SET delivered=? WHERE id=?",delivered,oid);if(delivered==number(o,"quantity")){
            String code=string(o,"code"),worker="p:"+string(o,"worker");long reward=number(o,"reward");require(s.balance("o:"+oid,code)==reward,"Пошкоджений резерв оплати.");long credit=Math.addExact(s.balance(worker,code),reward);require(credit<=CurrencyService.MAX_MONEY,"Ліміт балансу виконавця.");s.setBalance("o:"+oid,code,0);s.setBalance(worker,code,credit);db.execute("UPDATE resource_orders SET status='COMPLETED' WHERE id=?",oid);db.execute("INSERT INTO order_claims VALUES(?,?,?)",oid,string(o,"issuer"),delivered);s.currencies.log(new Actor(string(o,"worker"),false),code,worker,"ORDER_PAYMENT",oid+" "+format(reward));log(oid,actor,"COMPLETE","Оплату автоматично передано виконавцю");
        }}else{var claim=db.one("SELECT * FROM order_claims WHERE id=?",oid);require(claim!=null&&number(claim,"quantity")>=n,"Пошкоджене сховище ресурсів.");db.execute("UPDATE order_claims SET quantity=quantity-? WHERE id=?",n,oid);}}
        db.execute("UPDATE order_item_ops SET status=? WHERE id=?",applied?"APPLIED":"CANCELLED",id);log(oid,actor,applied?"ITEMS":"ROLLBACK",id+" "+n);return null;
    });}
    private void stop(Map<String,Object> o,Actor actor,String status) throws SQLException {
        String id=string(o,"id"),issuer=string(o,"issuer"),code=string(o,"code");require(!uncertain(id),"Спочатку перевірте незавершену передачу.");long reward=number(o,"reward");require(s.balance("o:"+id,code)==reward,"Пошкоджений резерв оплати.");long refund=Math.addExact(s.balance(issuer,code),reward);require(refund<=CurrencyService.MAX_MONEY,"Ліміт повернення.");s.setBalance(issuer,code,refund);s.setBalance("o:"+id,code,0);if(number(o,"delivered")>0)db.execute("INSERT INTO order_claims VALUES(?,?,?)",id,"p:"+string(o,"worker"),number(o,"delivered"));db.execute("UPDATE resource_orders SET status=? WHERE id=?",status,id);log(id,actor,status,"Оплату повернено замовнику; часткові ресурси — виконавцю");
    }
    public void cancel(Actor actor,String id){db.transaction(()->{var o=get(id);require(Set.of("OPEN","WORKING").contains(string(o,"status")),"Замовлення вже завершено.");if(!actor.id().equals(string(o,"worker")))owned(actor,string(o,"issuer"));stop(o,actor,"CANCELLED");return null;});}
    public void tick(){db.transaction(()->{for(var o:db.query("SELECT * FROM resource_orders WHERE status IN ('OPEN','WORKING') AND expires<=?",s.now()))if(!uncertain(string(o,"id")))stop(o,new Actor("система",true),"EXPIRED");return null;});}
    public List<Map<String,Object>> list() throws SQLException {return db.query("SELECT * FROM resource_orders ORDER BY created DESC LIMIT 500");}
    public List<Map<String,Object>> history(String id) throws SQLException {get(id);return db.query("SELECT * FROM order_history WHERE id=? ORDER BY seq DESC LIMIT 40",id);}
    public List<Map<String,Object>> pending() throws SQLException {return db.query("SELECT * FROM order_item_ops WHERE status='PREPARED' ORDER BY created LIMIT 50");}
    public long claimable(Actor actor,String id) throws SQLException {var claim=db.one("SELECT * FROM order_claims WHERE id=?",id);if(claim==null)return 0;owned(actor,string(claim,"owner"));return number(claim,"quantity");}
}
